// Des: Live vendor transport with deadline, key files, adapter dispatch
// Flo: worker thread sends HTTP (GET/POST) > caller polls to deadline > Real backend loads key file > picks adapter by vendor > redacts the key from errors
// I/O: Http (adapters) > Back; Req + vendor (ladder) > Rsp; keys read from vend_keyz_dirz/<vend>.key (first line, trimmed)
// ===================================================================
const std = @import("std"); const http = std.http; const fla2 = std.compress.flate; const base = @import("nt-vend-base.zig"); const zenr = @import("nt-vend-zenr.zig"); const deco = @import("nt-vend-deco.zig"); const brig = @import("nt-vend-brig.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .poll = 10, .maxb = 20 << 20, .trnb = 8192, .redb = 4096, .keyz = 4096 };
const Jobz = struct { allo: std.mem.Allocator, iozz: std.Io, urlz: []u8, auth: []u8, ctyp: []u8, body: []u8, post: bool, meth: []u8, heds: []http.Header, stat: std.atomic.Value(u8) = .init(0), resz: anyerror!base.Back = error.Unexpected,
fn kill(self: *Jobz) void { const allo = self.allo; allo.free(self.urlz); allo.free(self.auth); allo.free(self.ctyp); allo.free(self.body); allo.free(self.meth); for (self.heds) |hedz| { allo.free(hedz.name); allo.free(hedz.value); } allo.free(self.heds); allo.destroy(self); } };
fn dozzRequ(jobz: *Jobz) !base.Back { const allo = jobz.allo; var clnt: http.Client = .{ .allocator = allo, .io = jobz.iozz }; defer clnt.deinit(); const uric = try std.Uri.parse(jobz.urlz); const mthd: http.Method = if (jobz.meth.len > 0) (std.meta.stringToEnum(http.Method, jobz.meth) orelse return error.BadMethod) else if (jobz.post) .POST else .GET; var req2 = try clnt.request(mthd, uric, .{ .keep_alive = false, .redirect_behavior = .unhandled, .extra_headers = jobz.heds, .headers = .{ .authorization = if (jobz.auth.len > 0) .{ .override = jobz.auth } else .default, .content_type = if (jobz.ctyp.len > 0) .{ .override = jobz.ctyp } else .default } }); defer req2.deinit(); if (jobz.post or mthd == .PUT) { req2.transfer_encoding = .{ .content_length = jobz.body.len }; const bodz = try allo.dupe(u8, jobz.body); defer allo.free(bodz); try req2.sendBodyComplete(bodz); } else { try req2.sendBodiless(); } var redb: [CF.redb]u8 = undefined; var resp = try req2.receiveHead(&redb); const code: u16 = @backingInt(resp.head.status); const trnb = try allo.alloc(u8, CF.trnb); defer allo.free(trnb); const winb = try allo.alloc(u8, fla2.max_window_len); defer allo.free(winb); var deco_: http.Decompress = undefined; const rdrz = resp.readerDecompressing(trnb, &deco_, winb); const body = rdrz.allocRemaining(allo, .limited(CF.maxb)) catch |err3| switch (err3) { error.StreamTooLong => return error.TooBig, error.OutOfMemory => return error.OutOfMemory, error.ReadFailed => return resp.bodyErr() orelse error.ReadFailed }; return .{ .code = code, .body = body }; }
fn work(jobz: *Jobz) void { jobz.resz = dozzRequ(jobz); if (jobz.stat.cmpxchgStrong(0, 1, .acq_rel, .acquire) != null) { if (jobz.resz) |back| jobz.allo.free(back.body) else |_| {} jobz.kill(); } }
fn hedsDupz(allo: std.mem.Allocator, srcz: []const base.Hdrz) ![]http.Header { const outp = try allo.alloc(http.Header, srcz.len); for (srcz, 0..) |hedz, ind3| outp[ind3] = .{ .name = try allo.dupe(u8, hedz.name), .value = try allo.dupe(u8, hedz.valu) }; return outp; }
pub const Live = struct { time_mill: u32 = 30000,
pub fn send(self: *Live) base.Send { return .{ .ctx2 = self, .call = cal2 }; }
fn cal2(ctx2: *anyopaque, gpaz: std.mem.Allocator, iozz: std.Io, htpz: base.Http) anyerror!base.Back { const self: *Live = @ptrCast(@alignCast(ctx2)); const jobz = try gpaz.create(Jobz); var armd = false; errdefer if (!armd) gpaz.destroy(jobz); jobz.* = .{ .allo = gpaz, .iozz = iozz, .urlz = try gpaz.dupe(u8, htpz.urlz), .auth = try gpaz.dupe(u8, htpz.auth), .ctyp = try gpaz.dupe(u8, htpz.ctyp), .body = try gpaz.dupe(u8, htpz.body), .post = htpz.post, .meth = try gpaz.dupe(u8, htpz.meth), .heds = try hedsDupz(gpaz, htpz.ext2) }; const thrd = std.Thread.spawn(.{}, work, .{jobz}) catch { jobz.kill(); return error.Unexpected; }; thrd.detach(); armd = true; const dead = std.Io.Clock.awake.now(iozz).toMilliseconds() + self.time_mill; while (jobz.stat.load(.acquire) != 1) { if (std.Io.Clock.awake.now(iozz).toMilliseconds() >= dead) { if (jobz.stat.cmpxchgStrong(0, 2, .acq_rel, .acquire) == null) return error.Timeout; break; } std.Io.sleep(iozz, .fromMilliseconds(CF.poll), .awake) catch {}; } const outp = jobz.resz; jobz.kill(); return outp; } };
pub const Real = struct { gpaz: std.mem.Allocator, conf: cfgz.Conf, keyd: []const u8, live: Live = .{},
pub fn bac2(self: *Real) base.Bac2 { return .{ .ctx2 = self, .call = cal2 }; }
pub fn keyzLoad(self: *Real, aren: std.mem.Allocator, iozz: std.Io, vend: base.Vend) ![]const u8 { const path = try std.fmt.allocPrint(aren, "{s}{s}{s}.key", .{ self.keyd, std.fs.path.sep_str, base.vendName(vend) }); const raws = std.Io.Dir.cwd().readFileAlloc(iozz, path, aren, .limited(CF.keyz)) catch return error.NoKey; const line = std.mem.sliceTo(std.mem.trim(u8, raws, " \t\r\n"), '\n'); const key2 = std.mem.trim(u8, line, " \t\r"); if (key2.len == 0) return error.NoKey; return key2; }
fn cal2(ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, vend: base.Vend, req2: base.Requ) anyerror!base.Res2 { const self: *Real = @ptrCast(@alignCast(ctx2)); const key2 = try self.keyzLoad(aren, iozz, vend); const sndz = self.live.send(); var res4 = switch (vend) { .zenr => try zenr.call(aren, self.gpaz, iozz, sndz, key2, req2), .deco => try deco.call(aren, self.gpaz, iozz, sndz, key2, req2), .brig => try brig.call(aren, self.gpaz, iozz, sndz, key2, self.conf.vend_zone_brig, req2), .mock => return error.NoKey }; res4.errz = try base.reda(aren, res4.errz, key2); return res4; } };
